import hashlib, json, time

MAX_STEPS, MAX_TOKENS, MAX_SECONDS, MAX_USD = 25, 400_000, 300, 2.00

def run(goal: str) -> str:
    msgs, seen, tokens, usd, t0 = [user(goal)], {}, 0, 0.0, time.monotonic()
    for _ in range(MAX_STEPS):
        if tokens > MAX_TOKENS or usd > MAX_USD or time.monotonic() - t0 > MAX_SECONDS:
            return escalate("budget exhausted", msgs)   # stop and hand off, don't spiral
        resp = llm(msgs, tools=TOOLS)
        tokens += resp.usage.total_tokens
        usd += price(resp.usage)
        msgs.append(resp.message)
        if not resp.tool_calls:
            return verify_or_escalate(resp.text, msgs)
        for call in resp.tool_calls:
            key = f"{call.name}:{json.dumps(call.args, sort_keys=True)}"
            sig = hashlib.sha256(key.encode()).hexdigest()
            seen[sig] = seen.get(sig, 0) + 1
            if seen[sig] >= 3:                            # same tool, same args, 3rd time
                return escalate(f"loop on {call.name}", msgs)
            try:
                out = call_with_timeout(TOOLS[call.name], call.args, seconds=30)
            except Exception as e:
                # Actionable error instead of a stack trace or silence
                out = {"error": type(e).__name__, "message": str(e)[:300],
                       "hint": HINTS.get(type(e).__name__, "fix the arguments or try another tool")}
            if seen[sig] == 2:
                out = {"result": out, "warning": "You already made this exact call. Change approach."}
            msgs.append(tool_result(call, out))
    return escalate("step budget exhausted", msgs)
